KG42.register("rules-c6b769a1973018446298dcad",{"id":"34-market_versus_price_scheduling::v141-c-R004","paper":"34-market_versus_price_scheduling","record":{"rule_id":"v141-c-R004","mechanism_id":"v141-a-M01","name":"Social-welfare clearing objective","process_stage":"clearing","market_meaning":"The ISO's social-welfare clearing objective applies when it considers demand bids. Scope: ISO system-level clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids. The ISO maximizes system social welfare, described as consumption payments minus generation costs, subject to power balance, unit constraints, transmission line limits, and transmission line power flow constraints. Scope: ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","independence_rationale":"Relations governed by the approved function clearing.social_welfare under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.social_welfare"],"E":[{"edge_id":"v141-c-R004-E001","source":"clearing.social_welfare","target":"bidding.demand","type":"conditional_on","constraint_ids":["v141-c-R004-C001"],"evidence_ids":["v141-b-g02-E21"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. | ISO system-level clearing within the DMO-mediated market-based scheduling arrangement.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23"]},"x":[{"variable_id":"v141-c-R004-x-D-bt","symbol":"D_{bt}","meaning":"Demand/load quantity at bus b in hour t in the ISO social-welfare clearing model; the Nomenclature defines D as the demand awarded from the ISO to the DMO, while (17)-(18) use D_{bt} at the bus-hour level.","kind":"operational","domain":"Indexed by t (hours) and b (buses); explicit numeric sign or bounds are not supplied in the quoted source.","unit":null,"indices":["b","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g02-E22","v141-b-g02-E23"]},{"variable_id":"v141-c-R004-x-P-it","symbol":"P_{it}","meaning":"Output power of generation unit/DER i in hour t in the ISO SCUC/OPF clearing model.","kind":"operational","domain":"Indexed by t and i; (19) imposes bounds through P_i^{min}, P_i^{max}, and binary I_{it}; no separate numeric bounds are supplied.","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g02-E23"]},{"variable_id":"v141-c-R004-x-I-it","symbol":"I_{it}","meaning":"Commitment state of dispatchable unit i in hour t, equal to 1 when committed and 0 otherwise.","kind":"operational","domain":"{0,1}, indexed by t and i.","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g02-E23"]},{"variable_id":"v141-c-R004-x-PL-lt","symbol":"PL_{lt}","meaning":"Power flow on transmission line l in hour t.","kind":"operational","domain":"Indexed by t and l; constrained in (22) by |PL_{lt}| \u003c= PL_l^{max}; no separate numeric bounds are supplied.","unit":null,"indices":["l","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g02-E23"]},{"variable_id":"v141-c-R004-x-theta-bt","symbol":"\\theta_{bt}","meaning":"Bus angle at bus b in hour t in the transmission-line power-flow relation (23).","kind":"operational","domain":"Indexed by t and b; no independent numeric bounds are supplied in the quoted source.","unit":null,"indices":["b","t"],"evidence_ids":["v141-b-g01-e003","v141-b-g02-E23"]}],"theta":[{"parameter_id":"v141-c-R004-theta-lambda-bt","symbol":"\\lambda_{bt}(D_{bt})","meaning":"Consumption benefit of aggregated loads at bus b in hour t, evaluated at D_{bt}; the source gives it as a function without a closed form.","value":{"kind":"symbolic","number_value":null,"text_value":"function of D_{bt}; explicit functional form not supplied"},"unit":null,"indices":["b","t"],"evidence_ids":["v141-b-g01-e004","v141-b-g02-E22"]},{"parameter_id":"v141-c-R004-theta-rho-it","symbol":"\\rho_{it}(P_{it})","meaning":"Generation cost function of units submitted to the ISO for unit i in hour t, evaluated at P_{it}; the source gives it as a function without a closed form.","value":{"kind":"symbolic","number_value":null,"text_value":"function of P_{it}; explicit functional form not supplied"},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-g01-e004","v141-b-g02-E22"]},{"parameter_id":"v141-c-R004-theta-P-i-min","symbol":"P_i^{\\min}","meaning":"Minimum output limit of unit i in Eq. (19).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-P-i-max","symbol":"P_i^{\\max}","meaning":"Maximum output limit of unit i in Eq. (19).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-E-i","symbol":"E_i","meaning":"Energy parameter for unit i in the energy constraint Eq. (20); the supplied quotation does not state its numeric value or sign.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-f-i","symbol":"f_i(P_{it}, I_{it})","meaning":"Generic unit-constraint function for unit i in Eq. (21); the source states that unit constraints include output, reserve, ramp, minimum up/down, fuel, and emission limits but does not expand them here.","value":{"kind":"symbolic","number_value":null,"text_value":"generic function; component constraints not expanded in supplied equations"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-PL-l-max","symbol":"PL_l^{\\max}","meaning":"Transmission-line flow limit for line l in Eq. (22).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l"],"evidence_ids":["v141-b-g01-e004","v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-B-lb","symbol":"B_{lb}","meaning":"Bus-to-line incidence coefficient B_{lb} appearing in the transmission-line power-flow equation (23).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l","b"],"evidence_ids":["v141-b-g02-E23"]},{"parameter_id":"v141-c-R004-theta-x-l","symbol":"x_l","meaning":"Line impedance for transmission line l, used in Eq. (23).","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["l"],"evidence_ids":["v141-b-g01-e004","v141-b-g02-E23"]}],"phi":[{"constraint_id":"v141-c-R004-C001","kind":"logical","role":"core","statement":"The ISO's social-welfare clearing objective applies when it considers demand bids. Scope: ISO system-level clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["clearing.social_welfare","bidding.demand"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E21"]},{"constraint_id":"v141-c-R004-C002","kind":"mathematical","role":"core","statement":"The ISO maximizes system social welfare, described as consumption payments minus generation costs, subject to power balance, unit constraints, transmission line limits, and transmission line power flow constraints. Scope: ISO system-level bid-based clearing within the DMO-mediated market-based scheduling arrangement. Condition: When the ISO considers demand bids.","expression":"\\max \\left\\{ \\sum_t \\sum_b \\lambda_{bt}(D_{bt}) - \\sum_t \\sum_i \\rho_{it}(P_{it}) \\right\\} \\quad (17)\n\\text{subject to}\n\\sum_{i\\in G_b} P_{it} - \\sum_{l\\in L_b} PL_{lt} = D_{bt}, \\quad \\forall t,\\forall b \\quad (18)\nP_i^{\\min} I_{it} \\le P_{it} \\le P_i^{\\max} I_{it}, \\quad \\forall t,\\forall i \\quad (19)\n\\sum_t P_{it} = E_i, \\quad \\forall i \\quad (20)\n\\sum_t f_i(P_{it},I_{it}) \\le 0, \\quad \\forall i \\quad (21)\n|PL_{lt}| \\le PL_l^{\\max}, \\quad \\forall t,\\forall l \\quad (22)\nPL_{lt} = \\sum_b \\frac{B_{lb}\\theta_{bt}}{x_l}, \\quad \\forall t,\\forall l \\quad (23)","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare"],"variable_refs":["v141-c-R004-x-D-bt","v141-c-R004-x-P-it","v141-c-R004-x-I-it","v141-c-R004-x-PL-lt","v141-c-R004-x-theta-bt"],"parameter_refs":["v141-c-R004-theta-lambda-bt","v141-c-R004-theta-rho-it","v141-c-R004-theta-P-i-min","v141-c-R004-theta-P-i-max","v141-c-R004-theta-E-i","v141-c-R004-theta-f-i","v141-c-R004-theta-PL-l-max","v141-c-R004-theta-B-lb","v141-c-R004-theta-x-l"],"evidence_ids":["v141-b-g02-E21","v141-b-g02-E23","v141-b-g02-E22"]}],"pi":[{"evidence_id":"v141-b-g02-E21","location":{"location_id":"src-b66ae5184e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"C. ISO","anchor_text":"the load shifting would require the inclusion of time-coupling m constraints among hourly bids. This","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The ISO receives the generation and transmission information from GENCOs and TRANSCOs, and demand bids from DMOs, solves the SCUC problem to determine units schedule followed by a security-constrained optimal power flow to determine unit dispatch, line flow, and LMPs. The ISO’s objective, when considering demand bids, will be to maximize the system social welfare, rather than minimizing the total operation cost, as formulated in (17)."},{"evidence_id":"v141-b-g02-E23","location":{"location_id":"src-b66ae5184e-p06-c1r4__v141-a-M01-clearing","page":6,"printed_page":null,"section":"C. ISO","anchor_text":"gr ho max λbt(Dbt) − ρit(Pit) (17) sc t b t i ne Pit − PLlt = Dbt ∀t, ∀b (18) co i∈Gb l∈Lb tot Pmini","equation_id":"Eqs. (18)-(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The ISO maximizes objective function (17) which is the system social welfare, i.e., consumption payments minus generation costs. This objective is subject to the power balance constraint (18), unit constraints (19)-(21), transmission line limits (22), and transmission line power flow (23). Unit constraints include unit output limits, unit spinning/operating reserve limit, ramp up/down rate limits, min up/down time limits, fuel limits, and emission limits. Details of the SCUC model can be found in [49].\n\\sum_{i \\in G_b} P_{it} - \\sum_{l \\in L_b} PL_{lt} = D_{bt} \\quad \\forall t, \\forall b \\tag{18}\nP_i^{\\min} I_{it} \\le P_{it} \\le P_i^{\\max} I_{it} \\quad \\forall t, \\forall i \\tag{19}\n\\sum_t P_{it} = E_i \\quad \\forall i \\tag{20}\n\\sum_t f_i(P_{it}, I_{it}) \\le 0 \\quad \\forall i \\tag{21}\n|PL_{lt}| \\le PL_l^{\\max} \\quad \\forall t, \\forall l \\tag{22}\nPL_{lt} = \\sum_b \\frac{B_{lb}\\theta_{bt}}{x_l} \\quad \\forall t, \\forall l \\tag{23}"},{"evidence_id":"v141-b-g01-e003","location":{"location_id":"src-b66ae5184e-p01-c2r3__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"DXmax Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"d Load demand. D The demand awarded from the ISO to the DMO. PD^M Assigned demand to microgrids by the DMO. DX The amount of load awarded to each segment of the bid. DX^max Segment in the variable load bid of the microgrid. I Commitment state of dispatchable unit (1 when committed, 0 otherwise). LS Load curtailment. P DER output power. P^M Scheduled power transfer from the DMO to the microgrid. PL Line flow. \\Delta P^M Power transfer deviation. \\Delta P^{M+} Positive power transfer deviation. \\delta Power transfer deviation indicator (1 when deviation is positive, 0 otherwise). \\theta Bus angle."},{"evidence_id":"v141-b-g01-e004","location":{"location_id":"src-b66ae5184e-p01-c2r2__v141-a-M01-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"ar- U Islanding indicator (1 when grid-connected, on 0 when islanded). his ν Penalty for scheduled p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"U Islanding indicator (1 when grid-connected, 0 when islanded). \\nu Penalty for scheduled power deviation. \\upsilon Value of lost load. x Line impedance. \\rho(P) Cost function of generation units submitted to the ISO. \\lambda(D) Consumption benefit of aggregated loads."},{"evidence_id":"v141-b-g02-E22","location":{"location_id":"src-b66ae5184e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"C. ISO","anchor_text":"the load shifting would require the inclusion of time-coupling m constraints among hourly bids. This","equation_id":"Eq. (17)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"\\max \\left\\{ \\sum_t \\sum_b \\lambda_{bt}(D_{bt}) - \\sum_t \\sum_i \\rho_{it}(P_{it}) \\right\\} \\tag{17}"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing"],"extras":{"decision_anchor":"clearing.social_welfare","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E21","quote":"The ISO’s objective, when considering demand bids, will be to maximize the system social welfare, rather than minimizing the total operation cost, as formulated in (17)."}],[{"evidence_id":"v141-b-g02-E23","quote":"The ISO maximizes objective function (17) which is the system social welfare, i.e., consumption payments minus generation costs. This objective is subject to the power balance constraint (18), unit constraints (19)-(21), transmission line limits (22), and transmission line power flow (23)."},{"evidence_id":"v141-b-g02-E21","quote":"The ISO’s objective, when considering demand bids, will be to maximize the system social welfare"}]],"C2_formalization":{"graph_sha256":"193e7edc14ffe185be57349d6bf24d32c8a0a70a19f0cce8ebd9d6007acc6f86","applicability":"formalized","reason":"The supplied source explicitly gives the ISO social-welfare objective as Eq. (17) and its SCUC/OPF constraint set as Eqs. (18)-(23). Constraint C002 is formalized from those equations; C001 is retained as the source's conditional applicability statement without inventing a separate logical formula. The B evidence remains unreviewed, and no independent source review is claimed.","bindings":[{"object_id":"v141-c-R004-C001","node_ids":["clearing.social_welfare","bidding.demand"],"edge_ids":["v141-c-R004-E001"],"rationale":"C001 is exactly the conditional applicability statement represented by frozen edge E001: social-welfare clearing is conditional on consideration of demand bids."},{"object_id":"v141-c-R004-C002","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"C002 formalizes the ISO social-welfare objective and SCUC/OPF constraints at clearing.social_welfare; E001 records the demand-bid condition for this branch."},{"object_id":"v141-c-R004-x-D-bt","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"D_{bt} appears in objective (17) and power-balance constraint (18) of the ISO social-welfare clearing model; E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-x-P-it","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"P_{it} appears in objective (17) and unit constraints (18)-(21) of the ISO social-welfare clearing model; E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-x-I-it","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"I_{it} is the commitment variable in unit constraints (19)-(21) of the ISO clearing model; E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-x-PL-lt","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"PL_{lt} appears in the ISO power balance (18), line-limit constraint (22), and transmission-line flow equation (23); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-x-theta-bt","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"\\theta_{bt} appears in the ISO transmission-line power-flow equation (23); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-lambda-bt","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"\\lambda_{bt}(D_{bt}) is the consumption-benefit term in the ISO social-welfare objective (17); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-rho-it","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"\\rho_{it}(P_{it}) is the generation-cost term in the ISO social-welfare objective (17); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-P-i-min","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"P_i^{\\min} is used in unit output constraint (19) of the ISO clearing model; E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-P-i-max","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"P_i^{\\max} is used in unit output constraint (19) of the ISO clearing model; E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-E-i","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"E_i is the energy parameter in ISO constraint (20); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-f-i","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"f_i(P_{it},I_{it}) is the generic unit-constraint function in ISO constraint (21); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-PL-l-max","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"PL_l^{\\max} is the transmission-line limit in ISO constraint (22); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-B-lb","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"B_{lb} is the incidence coefficient in the ISO transmission-line flow equation (23); E001 records the demand-bid scope condition."},{"object_id":"v141-c-R004-theta-x-l","node_ids":["clearing.social_welfare"],"edge_ids":["v141-c-R004-E001"],"rationale":"x_l is the line impedance in the ISO transmission-line flow equation (23); E001 records the demand-bid scope condition."}],"revision_requests":[]}},"quarantined_references":[]}});
